#include <bits/stdc++.h>
using namespace std;

const long long mod = 1000000007;

long long modPower(long long base, long long exponent) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent % 2 == 1) result = result * base % mod;
        base = base * base % mod;
        exponent /= 2;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, colors;
    cin >> n >> colors;
    if (n == 1) {
        cout << colors << '\n';
        return 0;
    }
    if (colors == 1 || (n >= 3 && colors == 2)) {
        cout << 0 << '\n';
        return 0;
    }
    long long answer = colors * (colors - 1) % mod;
    answer = answer * modPower(colors - 2, n - 2) % mod;
    cout << answer << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> x(n), y(n);
    for (int i = 0; i < n; ++i) cin >> x[i] >> y[i];
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());
    long long medianX = x[n / 2], medianY = y[n / 2];
    long long totalDistance = 0;
    for (int i = 0; i < n; ++i) {
        totalDistance += llabs(x[i] - medianX) + llabs(y[i] - medianY);
    }
    cout << totalDistance << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> pieces(2 * n);
    long long totalSize = 0;
    for (int i = 0; i < n; ++i) {
        cin >> pieces[i];
        pieces[i + n] = pieces[i];
        totalSize += pieces[i];
    }
    if (totalSize % 10 != 0) {
        cout << "No\n";
        return 0;
    }
    long long target = totalSize / 10, windowSum = 0;
    int right = 0;
    for (int left = 0; left < n; ++left) {
        while (right < left + n && windowSum < target) {
            windowSum += pieces[right];
            ++right;
        }
        if (windowSum == target) {
            cout << "Yes\n";
            return 0;
        }
        windowSum -= pieces[left];
    }
    cout << "No\n";
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, edgeCount;
    cin >> n >> edgeCount;
    vector<int> lowerNeighbors(n + 1);
    for (int i = 0; i < edgeCount; ++i) {
        int first, second;
        cin >> first >> second;
        ++lowerNeighbors[max(first, second)];
    }
    int answer = 0;
    for (int vertex = 1; vertex <= n; ++vertex) {
        if (lowerNeighbors[vertex] == 1) ++answer;
    }
    cout << answer << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string text;
    cin >> n >> text;
    int lastO = 0, lastX = 0;
    long long answer = 0;
    for (int position = 1; position <= n; ++position) {
        if (text[position - 1] == 'o') lastO = position;
        else lastX = position;
        answer += min(lastO, lastX);
    }
    cout << answer << '\n';
}
